import {makeDeck,explanation} from './engine.js';
import {LocalSave,DEFAULT_AVATAR,WORLDS,BADGES,summarize,earnedBadges,recordRun,practiceDeck} from './progress.js';
import {Session} from './session.js';
import {drawAvatar} from './avatar.js';

const app=document.querySelector('#app');
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error();},setItem(){throw Error();}};}
const save=new LocalSave(storage);
let originalAvatar=null;
let page='missions',selected=Array.from({length:10},(_,i)=>i),roundSize=10,world='cosmos',smart=false,session=null,run=null,newBadges=[],editor=null,leaving=false,detailId=null,formError='';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const player=()=>save.data.players.find(p=>p.id===save.data.activeId);
const currentWorld=()=>WORLDS.find(w=>w.id===world)||WORLDS[0];
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const portrait=(p,cls='')=>`<canvas class="avatar ${cls}" data-avatar="${esc(p?.id||'draft')}" role="img" aria-label="${esc(p?.name||'Your')} pixel avatar"></canvas>`;
const percent=(a,b)=>b?`${Math.round(a/b*100)}%`:'—';
const date=x=>new Date(x).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
function heading(kicker,title,body=''){return `<div class="view-heading"><div class="eyebrow">${kicker}</div><h1>${title}</h1>${body?`<p>${body}</p>`:''}</div>`;}
function render(focus=false){
 const p=player();document.body.dataset.world=world;
 document.querySelector('#player-nav').innerHTML=p?`${portrait(p,'tiny')}<span>${esc(p.name)}</span>`:'Choose player';
 document.querySelector('#player-nav').disabled=page==='play';
 document.querySelector('#main-nav').hidden=!p||page==='play';
 document.querySelectorAll('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===page);el.setAttribute('aria-current',el.dataset.nav===page?'page':'false');});
 let body;
 if(editor)body=editorView();else if(!p||page==='players')body=playersView();else if(page==='missions')body=missionsView(p);else if(page==='play')body=playView();else if(page==='finish')body=finishView(p);else if(page==='achievements')body=badgesView(p);else body=reportsView(p);
 app.innerHTML=`${save.error?`<div class="save-warning" role="alert">${esc(save.error)}</div>`:''}${body}`;
 app.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action));
 document.querySelectorAll('[data-avatar]').forEach(canvas=>{const target=canvas.dataset.avatar==='draft'?editor:save.data.players.find(x=>x.id===canvas.dataset.avatar);drawAvatar(canvas,target?.avatar);});
 if(editor)app.querySelectorAll('[data-hair-preview]').forEach(canvas=>drawAvatar(canvas,{...editor.avatar,hair:+canvas.dataset.hairPreview,accessory:'none'}));
 bind();if(focus){app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
}
function playersView(){return `<section class="players-view">${heading('CHOOSE YOUR SAVE SLOT','Who’s playing?','Every adventurer gets their own avatar, stars, and discoveries.')}<div class="save-slot-art" aria-hidden="true"><img src="./circuit-world.png" alt=""><img src="./sky-world.png" alt=""></div><div class="player-grid">${save.data.players.map(p=>`<article class="player-card">${portrait(p)}<h2>${esc(p.name)}</h2><p>${p.runs.length} missions · ${summarize(p.runs).correct} stars</p>${btn('Let’s play →','choose:'+p.id,'primary')}${btn('Customize','edit:'+p.id,'quiet')}</article>`).join('')}<button class="new-player" data-action="new"><span>+</span>Create a player</button></div><p class="local-note">Saved in this browser, on this device. No account needed.<br>Clearing browser data removes these profiles. Saves don’t sync between devices.</p></section>`;}
function editorView(){const a=editor.avatar;
 const colors=(label,key,items)=>`<fieldset class="palette"><legend>${label}<span data-color-name>${items.find(x=>x[0]===a[key])?.[1]||'Custom'}</span></legend><div class="swatch-row">${items.map(([v,n])=>`<button type="button" class="swatch ${a[key]===v?'chosen':''}" style="--swatch:${v}" data-color="${key}:${v}" aria-label="${label}: ${n}" aria-pressed="${a[key]===v}" title="${n}">${a[key]===v?'✓':''}</button>`).join('')}</div></fieldset>`;
 return `<section class="editor studio">${heading('PLAYER STUDIO',editor.id?'A hero that feels like you.':'Make your adventure yours.')}<form id="avatar-form"><div class="editor-preview"><div class="portrait-frame">${portrait({...editor,id:'draft'})}</div><div class="eyebrow">YOUR ADVENTURE PORTRAIT</div><p>Pick a look. Make it yours.</p><div class="preview-tools">${btn('Shuffle look','shuffle-avatar','quiet','type="button"')}${btn('Reset changes','reset-avatar','quiet','type="button"')}</div><div class="studio-buddy"><span class="bot-sprite idle" role="img" aria-label="Your robot buddy"></span><span>Your bot buddy is ready.</span></div></div><div class="editor-fields"><label class="field">Player nickname<input id="nickname" maxlength="20" autocomplete="off" value="${esc(editor.name)}" placeholder="Choose a nickname" required></label><fieldset class="portrait-options"><legend>Hair style</legend><div class="hair-picker">${['Spiky','Curly','Long','Buzz cut','Side sweep','Tied up'].map((name,i)=>`<button type="button" class="hair-option ${a.hair===i?'chosen':''}" data-action="hair:${i}" aria-pressed="${a.hair===i}"><canvas data-hair-preview="${i}" aria-hidden="true"></canvas><span>${name}</span></button>`).join('')}</div></fieldset>${colors('Hair color','hairColor',[['#322735','Midnight'],['#54351f','Chestnut'],['#edc86c','Golden'],['#c75f3f','Copper'],['#8653b7','Violet'],['#5cc7cb','Aqua']])}<div class="studio-pair">${colors('Skin tone','skin',[['#f5d1b3','Light'],['#e9ad79','Warm'],['#c68a5c','Tan'],['#9b6145','Brown'],['#643e32','Deep']])}${colors('Eye color','eyes',[['#497eb8','Blue'],['#408850','Green'],['#69452d','Brown'],['#55566f','Gray']])}</div><fieldset class="portrait-options"><legend>Gear</legend><div class="gear-picker">${[['none','No gear'],['glasses','Glasses'],['headphones','Headphones'],['cap','Explorer cap']].map(([value,label],i)=>`<button type="button" data-action="gear:${value}" class="gear-option ${a.accessory===value?'chosen':''}" aria-pressed="${a.accessory===value}">${i?`<span class="gear-image gear-${value}"></span>`:'<span class="gear-empty">—</span>'}<span>${label}</span></button>`).join('')}</div></fieldset>${colors('Outfit color','shirt',[['#795bce','Violet'],['#e26755','Coral'],['#4d9cca','Blue'],['#5caa73','Green'],['#edbd51','Gold'],['#dd7faf','Pink']])}<fieldset class="portrait-options"><legend>Outfit pattern</legend><div class="pattern-picker">${[['plain','Solid'],['stripes','Stripes'],['checkers','Checkers'],['jersey','Team jersey']].map(([value,label])=>`<button type="button" data-action="pattern:${value}" class="${a.style===value?'chosen':''}" aria-pressed="${a.style===value}">${label}</button>`).join('')}</div></fieldset>${colors('Portrait backdrop','backdrop',[['#243c60','Midnight'],['#47665e','Forest'],['#644267','Plum'],['#f0dbc0','Sand']])}<p class="form-error" role="alert">${esc(formError)}</p><div class="editor-actions"><button class="primary" type="submit">Save player →</button>${btn('Cancel','cancel-edit','quiet','type="button"')}</div></div></form><p class="local-note">Your nickname, portrait and progress stay in this browser.</p></section>`;
}
function missionsView(p){const w=currentWorld(),s=summarize(p.runs);return `<section class="mission-home"><div class="welcome"><div><div class="eyebrow">WELCOME BACK, ${esc(p.name).toUpperCase()}</div><h1>Your next<br><em>great discovery.</em></h1></div><div class="player-score">${portrait(p,'small')}<div><strong>✦ ${s.correct}</strong><span>stars collected</span></div></div></div><div class="mission-layout"><div class="world-column"><div class="world-stage"><img src="./${w.image}" alt="${w.character} in ${w.name}, a colorful pixel-art adventure"><div class="world-caption"><span>WORLD ${WORLDS.indexOf(w)+1} / ${WORLDS.length}</span><h2>${w.name}</h2><p>${w.subtitle}</p></div></div><div class="world-picker" aria-label="Choose a world">${WORLDS.map(x=>`<button data-action="world:${x.id}" aria-pressed="${world===x.id}" class="${world===x.id?'selected':''}"><img src="./${x.image}" alt=""><span>${x.name}</span></button>`).join('')}</div><div class="buddy-note"><span class="bot-sprite idle" aria-hidden="true"></span><p><strong>Your bot buddy is on your team.</strong><br>Good tries count. Let’s learn something together.</p></div></div><div class="mission-panel"><div class="panel-heading"><span class="step">×</span><div><h2>Choose your mission</h2><p>Pick one table or mix a few.</p></div></div><div class="presets">${btn('All','all',selected.length===10?'selected':'')}${btn('Odds','odd',selected.join()==='1,3,5,7,9'?'selected':'')}${btn('Evens','even',selected.join()==='0,2,4,6,8'?'selected':'')}${btn('Clear','clear')}</div><div class="tables">${Array.from({length:10},(_,i)=>`<button data-action="table:${i}" class="table ${selected.includes(i)?'selected':''}" aria-pressed="${selected.includes(i)}">${i}<small>times table</small></button>`).join('')}</div><p class="hint">Every table includes ×0 through ×9.</p><label class="field round">Mission length<select id="length"><option value="10" ${roundSize===10?'selected':''}>10 facts · quick quest</option><option value="20" ${roundSize===20?'selected':''}>20 facts · big adventure</option><option value="all" ${roundSize==='all'?'selected':''}>Every selected fact</option></select></label><label class="toggle"><input id="smart" type="checkbox" ${smart?'checked':''}> Practice for me <span>Prioritize facts that need another try.</span></label><button class="primary start" data-action="start" ${selected.length?'':'disabled'}>Let’s play <span>→</span></button><div class="parent-tip"><strong>Grown-up is the controller</strong><p>Swipe right for correct, left to learn. Missed facts return once during the mission. No timer.</p></div></div></div></section>`;}
function playView(){const {a,b,retry}=session.card,f=session.feedback,w=currentWorld(),pose=f===true?'cheer':f===false?'teach':'idle';return `<section class="play"><div class="play-toolbar">${btn('← Leave mission','leave','quiet')}<span>${esc(player()?.name)} · ${w.name}</span><strong class="stars">✦ ${session.stars}</strong></div>${leaving?`<div class="leave-panel" role="alert"><h2>Leave this mission?</h2><p>Only completed missions are saved. Your earlier missions are safe.</p>${btn('Keep playing','stay','primary')}${btn('Leave without saving','discard','quiet')}</div>`:''}<div class="progress-label"><span>Card ${session.position+1} of ${session.queue.length}${retry?' · Practice again':''}</span><span>${run.tables.length===10?'All tables':run.tables.join(', ')+' tables'}</span></div><progress aria-label="Mission progress" value="${session.position}" max="${session.queue.length}"></progress><div class="bot-adventure" style="--world-art:url('./${w.image}')"><div class="bot-stage ${pose}"><span class="bot-sprite ${pose}" role="img" aria-label="Your robot buddy ${pose==='cheer'?'celebrating':pose==='teach'?'helping you learn':'thinking with you'}"></span><div class="bot-speech" aria-live="polite">${f===null?(retry?'Let’s try this one together again.':'Ready to power up? Take your time.'):f?'Power collected! You did it!':'We can build this answer together.'}</div></div></div><div class="flashcard ${f===true?'success':f===false?'learning':''}" id="card"><div class="eyebrow">${f===null?(retry?'A FAMILIAR DISCOVERY':'YOUR NEXT DISCOVERY'):f?'STAR COLLECTED':'LET’S BUILD IT TOGETHER'}</div><div class="equation">${a} <span>×</span> ${b}${f!==null?`<span>=</span> ${a*b}`:''}</div>${f===null?'<p class="card-prompt">What do you think?</p>':f?`<h2>${retry?'Look at that progress!':['Stellar work!','You figured it out!','Your brain is powering up!'][session.position%3]}</h2><p>${retry?'You tried again and made a discovery.':'Another star for your adventure.'}</p><div class="power-reward" aria-hidden="true">✦ &nbsp; ✦ &nbsp; ✦</div>`:`<h2>Good try. Let’s take a closer look.</h2><p>Help your bot count ${a} groups of ${b} energy tiles.</p><div class="groups power-groups">${a&&b?Array.from({length:a},(_,i)=>`<div class="power-pack"><div class="group" aria-label="Group ${i+1}: ${b} energy tiles">${'<i></i>'.repeat(b)}</div><span>${(i+1)*b}</span></div>`).join(''):''}</div><p class="addition">${explanation(a,b)}</p><p class="gentle">Say it together: ${a} times ${b} equals ${a*b}.</p>`}</div>${f===null?`<div class="answer-controls">${btn('← Let’s practice','wrong','practice')}${btn('Got it! →','right','primary')}</div>`:`<div class="continue">${btn('Continue →','next','primary')}</div>`}<div class="under-card">${btn('↶ Undo','undo','quiet',session.position===0&&f===null?'disabled':'')}<p class="hint">Swipe the card or use buttons · Keyboard ← / →<br>Practice-again cards may extend your mission.</p></div></section>`;}
function finishView(p){const originals=run.answers.filter(x=>!x.retry),first=originals.filter(x=>x.ok).length;return `<section class="finish"><div class="finish-bot bot-sprite cheer" role="img" aria-label="Your robot celebrating"></div><div class="finish-art"><img src="./${currentWorld().image}" alt="${currentWorld().character} celebrating the mission"></div><div class="eyebrow">MISSION COMPLETE</div><h1>You kept<br><em>discovering!</em></h1><p>Nice exploring, ${esc(p.name)}.</p><div class="results"><div><strong>${run.answers.filter(x=>x.ok).length}</strong><span>stars collected</span></div><div><strong>${run.answers.length}</strong><span>cards explored</span></div></div><p>${first} of ${originals.length} first tries correct. Every retry helps you grow.</p>${newBadges.length?`<div class="new-badges"><h2>Achievement unlocked!</h2>${newBadges.map(id=>{const b=BADGES.find(b=>b.id===id);return `<span>${b.icon} ${b.title}</span>`;}).join('')}</div>`:''}<p class="local-note">${save.error?'Saved for this session only. See the message above.':'Mission saved to '+esc(p.name)+'’s history on this device.'}</p>${btn('Choose another mission →','missions','primary')}${btn('See my progress','reports','quiet')}</section>`;}
function badgesView(p){const s=summarize(p.runs),earned=new Set(earnedBadges(p.runs));return `<section>${heading('YOUR TROPHY ROOM','Small steps. Real achievements.','Earn badges by exploring, practicing, and trying again.')}<div class="badge-grid">${BADGES.map(b=>{const n=Math.min(b.goal,b.value(s,p.runs));return `<article class="badge ${earned.has(b.id)?'earned':''}"><div class="badge-icon">${b.icon}</div><span class="badge-state">${earned.has(b.id)?'UNLOCKED':'IN PROGRESS'}</span><h2>${b.title}</h2><p>${b.description}</p><progress aria-label="${b.title}" value="${n}" max="${b.goal}"></progress><small>${n} / ${b.goal}</small></article>`;}).join('')}</div></section>`;}
function reportsView(p){const s=summarize(p.runs),detail=p.runs.find(r=>r.id===detailId);return `<section>${heading('PLAYER JOURNAL',esc(p.name)+'’s discoveries.','A little practice adds up. These reports include completed missions only.')}<div class="report-stats"><article><strong>${s.runs}</strong><span>missions completed</span></article><article><strong>${s.attempts}</strong><span>cards explored</span></article><article><strong>${percent(s.firstCorrect,s.firstAttempts)}</strong><span>correct on first try</span></article><article><strong>${s.comebacks}</strong><span>successful retries</span></article></div><div class="report-layout"><div class="report-panel"><h2>Times-table progress</h2><p class="hint">First-try results across completed missions. “Explore” counts different facts tried.</p><div class="table-report">${s.tables.map(t=>`<div class="table-row"><strong>${t.a}×</strong><div><div class="table-summary"><span>${t.seen.size}/10 explored</span><span>${percent(t.correct,t.attempts)} first try</span></div><progress aria-label="${t.a} table facts explored" value="${t.seen.size}" max="10"></progress></div>${btn(t.needs.size?'Practice '+t.needs.size:'Explore','practice-table:'+t.a,'quiet')}</div>`).join('')}</div><p class="hint">Practice counts facts whose latest recorded answer needs another try.</p></div><div class="report-panel"><div class="history-title"><h2>Mission history</h2>${p.runs.length?btn('Export CSV','export','quiet'):''}</div>${p.runs.length?`<div class="history">${[...p.runs].reverse().map(r=>{const o=r.answers.filter(x=>!x.retry),w=WORLDS.find(w=>w.id===r.world)||WORLDS[0];return `<button class="history-run ${r.id===detailId?'selected':''}" data-action="detail:${r.id}" aria-expanded="${r.id===detailId}"><span><strong>${w.name}</strong><small>${esc(date(r.endedAt))} · ${r.tables.length===10?'All tables':r.tables.join(', ')+' tables'}</small></span><span>${o.filter(x=>x.ok).length}/${o.length}<small>first try · View</small></span></button>`;}).join('')}</div>`:'<div class="empty-state"><span>✦</span><h3>Your story starts here.</h3><p>Finish a mission to see it in your journal.</p></div>'}${detail?`<div class="run-detail"><h3>Mission details</h3><p>${esc(date(detail.endedAt))} · ${detail.answers.length} cards</p><div class="fact-results">${detail.answers.map(x=>`<span class="${x.ok?'fact-correct':'fact-practice'}">${x.a} × ${x.b} = ${x.a*x.b}<small>${x.ok?'Got it':'Practiced'}${x.retry?' · Retry':''}</small></span>`).join('')}</div></div>`:''}</div></div><p class="local-note">Progress belongs to this player in this browser. It does not sync to other devices.</p></section>`;}
function bind(){
 const name=app.querySelector('#nickname');if(name)name.oninput=()=>editor.name=name.value;
 app.querySelectorAll('[data-avatar-setting]').forEach(el=>el.onchange=()=>{editor.avatar[el.dataset.avatarSetting]=el.dataset.avatarSetting==='hair'?+el.value:el.value;refreshAvatar();});
 app.querySelectorAll('[data-color]').forEach(el=>el.onclick=()=>{const [k,v]=el.dataset.color.split(':');editor.avatar[k]=v;const group=el.closest('fieldset');group.querySelector('[data-color-name]').textContent=el.title;group.querySelectorAll('button').forEach(b=>{b.classList.toggle('chosen',b===el);b.setAttribute('aria-pressed',b===el);b.textContent=b===el?'✓':'';});refreshAvatar();});
 const form=app.querySelector('#avatar-form');if(form)form.onsubmit=e=>{e.preventDefault();savePlayer();};
 const length=app.querySelector('#length');if(length)length.onchange=()=>roundSize=length.value==='all'?'all':+length.value;
 const smartEl=app.querySelector('#smart');if(smartEl)smartEl.onchange=()=>smart=smartEl.checked;
 const card=app.querySelector('#card');if(card){let point;card.onpointerdown=e=>{if(session.feedback!==null||leaving)return;point={x:e.clientX,y:e.clientY};card.setPointerCapture(e.pointerId);};card.onpointerup=e=>{if(!point)return;const dx=e.clientX-point.x,dy=e.clientY-point.y;point=null;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.3)act(dx>0?'right':'wrong');};card.onpointercancel=()=>point=null;}
}
function refreshAvatar(){const c=app.querySelector('[data-avatar="draft"]');if(c)drawAvatar(c,editor.avatar);app.querySelectorAll('[data-hair-preview]').forEach(canvas=>drawAvatar(canvas,{...editor.avatar,hair:+canvas.dataset.hairPreview,accessory:'none'}));}
function savePlayer(){const name=editor.name.trim();if(!name){formError='Choose a nickname first.';render();return;}if(save.data.players.some(p=>p.id!==editor.id&&p.name.toLowerCase()===name.toLowerCase())){formError='That nickname already has a save slot. Try another.';render();return;}
 const id=editor.id||crypto.randomUUID(),avatar={...editor.avatar};save.update(data=>{const existing=data.players.find(p=>p.id===id);if(existing){existing.name=name;existing.avatar=avatar;}else data.players.push({id,name,avatar,runs:[],createdAt:new Date().toISOString()});data.activeId=id;});editor=null;formError='';page='missions';render(true);
}
function start(){const p=player();if(!p||!selected.length)return;const limit=roundSize==='all'?selected.length*10:roundSize,cards=smart?practiceDeck(p,selected,limit):makeDeck(selected).slice(0,limit);session=new Session(cards);run={id:crypto.randomUUID(),playerId:p.id,world,tables:[...selected],smart,startedAt:new Date().toISOString(),answers:[]};newBadges=[];leaving=false;page='play';render(true);}
function complete(){run.answers=[...session.answers];run.endedAt=new Date().toISOString();save.update(data=>{const p=data.players.find(x=>x.id===run.playerId);if(p)newBadges=recordRun(p,run);data.activeId=run.playerId;});page='finish';render(true);}
function act(action){const [type,arg]=action.split(':');
 if(editor&&['hair','gear','pattern','reset-avatar','shuffle-avatar'].includes(type)){
  if(type==='hair')editor.avatar.hair=+arg;
  if(type==='gear')editor.avatar.accessory=arg;
  if(type==='pattern')editor.avatar.style=arg;
  if(type==='reset-avatar')editor.avatar={...originalAvatar};
  if(type==='shuffle-avatar'){const pick=a=>a[Math.floor(Math.random()*a.length)];editor.avatar={...editor.avatar,hair:Math.floor(Math.random()*6),hairColor:pick(['#322735','#54351f','#edc86c','#c75f3f','#8653b7','#5cc7cb']),skin:pick(['#f5d1b3','#e9ad79','#c68a5c','#9b6145','#643e32']),eyes:pick(['#497eb8','#408850','#69452d','#55566f']),shirt:pick(['#795bce','#e26755','#4d9cca','#5caa73','#edbd51','#dd7faf']),accessory:pick(['none','glasses','headphones','cap']),style:pick(['plain','stripes','checkers','jersey'])};}
  render();return;
 }
 if(type==='new'||type==='edit'){const p=save.data.players.find(p=>p.id===arg);editor=p?{id:p.id,name:p.name,avatar:{...DEFAULT_AVATAR,...p.avatar}}:{name:'',avatar:{...DEFAULT_AVATAR}};originalAvatar={...editor.avatar};formError='';render(true);return;}
 if(type==='cancel-edit'){editor=null;formError='';page='players';render(true);return;}
 if(type==='choose'){save.update(d=>d.activeId=arg);page='missions';render(true);return;}
 if(type==='world'){world=arg;render();return;}
 if(['all','odd','even','clear'].includes(type)){selected=Array.from({length:10},(_,i)=>i).filter(i=>type==='all'||(type==='odd'&&i%2===1)||(type==='even'&&i%2===0));render();return;}
 if(type==='table'){const n=+arg;selected=selected.includes(n)?selected.filter(x=>x!==n):[...selected,n].sort((a,b)=>a-b);render();return;}
 if(type==='start'){start();return;}
 if(type==='practice-table'){selected=[+arg];smart=true;page='missions';render(true);return;}
 if(type==='detail'){detailId=detailId===arg?null:arg;render();return;}
 if(type==='export'){exportHistory();return;}
 if(page==='play'){
  if(type==='leave'){leaving=true;render();return;}if(type==='stay'){leaving=false;render();return;}if(type==='discard'){session=null;run=null;leaving=false;page='missions';render(true);return;}if(leaving)return;
  if(type==='right'||type==='wrong'){session.mark(type==='right');render();return;}
  if(type==='undo'){session.undo();render();return;}
  if(type==='next'){session.next();if(session.complete)complete();else render();return;}
 }
 if(['players','missions','reports','achievements'].includes(type)&&page!=='play'){editor=null;page=type;render(true);}
}
function exportHistory(){const p=player(),rows=[['Completed','World','Tables','First try correct','First try total','Retries','Retry correct','Stars']];for(const r of p.runs){const original=r.answers.filter(x=>!x.retry),retry=r.answers.filter(x=>x.retry);rows.push([r.endedAt,r.world,r.tables.join(' / '),original.filter(x=>x.ok).length,original.length,retry.length,retry.filter(x=>x.ok).length,r.answers.filter(x=>x.ok).length]);}const csv=rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='star-quest-history.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>act(el.dataset.nav));
document.querySelector('#player-nav').onclick=()=>act('players');
document.addEventListener('keydown',e=>{if(e.repeat||/SELECT|INPUT|BUTTON|TEXTAREA/.test(e.target.tagName))return;if(page==='play'&&!leaving&&session.feedback===null&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();act(e.key==='ArrowRight'?'right':'wrong');}});
window.addEventListener('beforeunload',e=>{if(page==='play'){e.preventDefault();e.returnValue='';}});
render();

